/// E168 补丁：式子后三项，待删占用与已承诺预留取测试账房给的那一对。
#[must_use]
pub fn pool_wide_commitments_with_the_ledger_for_tests(
    checkpoint_reserve_pool: BytesSummedOverAllReplicas,
) -> PoolWideCommitments {
    match LEDGER_FOR_TESTS.with(std::cell::Cell::get) {
        Some((pending_delete, committed_reservation)) => PoolWideCommitments {
            pending_delete: BytesSummedOverAllReplicas(pending_delete),
            committed_reservation: BytesSummedOverAllReplicas(committed_reservation),
            checkpoint_reserve_pool,
        },
        None => PoolWideCommitments::of_the_first_version(checkpoint_reserve_pool),
    }
}

/// E168 补丁（只供测试）：ckpt_cost 里分配记录树那一项（K1），根层级从这一版的根节点头现读，与
/// `checkpoint_cost_of_the_version_to_build_on` 同一算法；装置拿它与本地按条款算的 K1 逐格比（停机条款 S4）。
#[must_use]
pub fn allocation_record_tree_positions_for_tests(
    version_to_build_on: &TransactionOutput,
    allocator: &PoolAllocator,
) -> u64 {
    let root_level_read_from_the_root_node_header = u8::try_from(
        version_to_build_on
            .position_addressed_tree_heights_read_from_the_root_node_headers()
            .allocation_record_tree
            .checked_sub(1)
            .expect("树高是根节点头里的层级 + 1，至少 1"),
    )
    .expect("码 2 头的层级是 1 字节");
    allocation_record_tree_positions_over_the_unit_areas(root_level_read_from_the_root_node_header, allocator)
}

