column4:
fn delete_path_hooks() -> DeletePathHooks {
    let _ = DELETE_PATH_PATCH_ABSENT_EXIT_CODE;
    DeletePathHooks {
        publish_unlink_batch: singlefs_core::transaction::publish_unlink_batch_for_tests::<SparseBlockDevice>,
        unlink_batch_change: |kept_data_units, size_after_the_batch| UserChange::UnlinkBatchForTests {
            kept_data_units,
            size_after_the_batch,
        },
        set_inode_written_with_zero_links: |inode| {
            singlefs_core::records::NLINK_ZERO_INODE_FOR_TESTS.with(|cell| cell.set(inode));
        },
        set_formula_judgement_skipped: |skipped| {
            singlefs_core::transaction::FORMULA_JUDGEMENT_SKIPPED_FOR_TESTS.with(|cell| cell.set(skipped));
        },
        formula_judgements_made: || singlefs_core::transaction::FORMULA_JUDGEMENTS_MADE_FOR_TESTS.with(std::cell::Cell::get),
        set_reclaim_switched_off: |switched_off| {
            singlefs_core::allocator::RECLAIM_SWITCHED_OFF_FOR_TESTS.with(|cell| cell.set(switched_off));
        },
        take_free_slots_recorded_at_each_root: || {
            singlefs_core::allocator::FREE_SLOTS_AT_ROOT_RECORDING_FOR_TESTS.with(|cell| std::mem::take(&mut *cell.borrow_mut()))
        },
        set_ledger: |ledger| {
            singlefs_core::admission::LEDGER_FOR_TESTS.with(|cell| cell.set(ledger));
        },
        allocation_record_tree_positions: singlefs_core::admission::allocation_record_tree_positions_for_tests,
    }
}
